import os,re
def closure(mods):
    seen=set(); st=list(mods)
    while st:
        m=st.pop()
        if m in seen: continue
        seen.add(m)
        p=m.replace('.','/')+'.lean'
        if not os.path.exists(p): continue
        for l in open(p):
            mm=re.match(r'^import\s+(\S+)',l)
            if mm and mm.group(1).startswith('AlgebraicJacobian'): st.append(mm.group(1))
    return seen
for target in ['AlgebraicJacobian.Picard.DivisorFamilyAffMapKit','AlgebraicJacobian.Picard.DivRepGlobalAffLift']:
    c=closure([target]); c.discard(target)
    missing=[m for m in sorted(c) if not os.path.exists('.lake/build/lib/lean/'+m.replace('.','/')+'.olean')]
    print(target, "deps",len(c), "missing oleans",len(missing))
    for m in missing[:15]: print("   MISSING",m)
EOF

